import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { BlockAssembler, createUserMessage } from '@deepseek-ai/dsh-llm';
const defaults = { enabled: false, probability: 5, minMessages: 3, cooldownSeconds: 300, dailyLimitPerGroup: 20, historyMessages: 12, minTextLength: 2, maxTextLength: 500, requireRecentActivitySeconds: 900, quietHoursEnabled: true, quietStart: '23:00', quietEnd: '08:00' };
// 被动回复窗口：QQ 官方 5 分钟内可用触发消息的 msg_id 回复；留 30 秒余量。
const PASSIVE_WINDOW_MS = 270_000;
const MAX_TOKENS = 2048;
const TIMEOUT_MS = 60_000;
function settings(global, group) {
    const pick = raw => (raw && typeof raw === 'object' ? raw : {});
    const s = { ...defaults, ...pick(global), ...pick(group) };
    for (const [key, min, max] of [['probability', 0, 100], ['minMessages', 1, 100], ['cooldownSeconds', 0, 86400], ['dailyLimitPerGroup', 0, 1000], ['historyMessages', 1, 100], ['minTextLength', 1, 5000], ['maxTextLength', 1, 5000], ['requireRecentActivitySeconds', 0, 86400]]) s[key] = typeof s[key] === 'number' && Number.isFinite(s[key]) ? Math.floor(Math.max(min, Math.min(max, s[key]))) : defaults[key];
    if (s.minTextLength > s.maxTextLength) s.minTextLength = s.maxTextLength;
    return s;
}
function quiet(s, now) {
    if (!s.quietHoursEnabled) return false;
    const parse = value => { const m = /^(\d{1,2}):(\d{2})$/.exec(value); return m && +m[1] < 24 && +m[2] < 60 ? +m[1] * 60 + +m[2] : null; };
    const start = parse(s.quietStart), end = parse(s.quietEnd);
    if (start === null || end === null || start === end) return false;
    const minute = now.getHours() * 60 + now.getMinutes();
    return start < end ? minute >= start && minute < end : minute >= start || minute < end;
}
function dayKey(d) { return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`; }
function isGroupText(msg) {
    return msg.kind === 'group' && msg.groupOpenid && !msg.senderIsBot && typeof msg.content === 'string' && !msg.attachments?.length;
}
function mentionsBot(msg) {
    return msg.rawEventType === 'GROUP_AT_MESSAGE_CREATE' || msg.mentions?.some?.(m => m?.is_you) || /<@!?[^>]+>/.test(msg.content);
}
function plain(msg) {
    return !mentionsBot(msg) && !msg.mentions?.length && !msg.refMsgIdx && !/<[^>]+>|\[CQ:|^\s*\//i.test(msg.content);
}
function cleanText(text) { return text.replace(/<@!?[^>]+>/g, '').replace(/\s+/g, ' ').trim(); }
export function proactiveReply(host, bot, config, logger, manager) {
    const groups = new Map();
    let cached = { global: {}, groups: {} }, checked = 0, loading, saveTimer, statusLoaded;
    const dir = process.env.SHINY_APP_FILES_DIR && join(process.env.SHINY_APP_FILES_DIR, '.dsh-qqbot');
    const path = dir && join(dir, 'proactive-reply.json');
    const statusPath = dir && join(dir, 'proactive-reply-state.json');
    const testPath = dir && join(dir, 'proactive-reply-test.json');
    // requireMention / 时区写进状态文件：App 据此提示"关掉必须@后主动回复不生效"，并显示 Node 实际使用的时区。
    // 注意：内置 Node 运行时没有编译 Intl（`ReferenceError: Intl is not defined`），
    // 时区只能取 App 通过环境变量传进来的 TZ，拿不到就留空由 UI 回退成 UTC 偏移。
    const timeZone = typeof process.env.TZ === 'string' ? process.env.TZ : '';
    const status = { schemaVersion: 1, requireMention: config.requireMention !== false, timeZone, utcOffsetMinutes: -new Date().getTimezoneOffset(), groups: {} };
    logger.info(`主动回复已加载 requireMention=${status.requireMention} TZ=${timeZone || '(未设置)'} offset=${status.utcOffsetMinutes}min`);
    function groupStatus(key) {
        return status.groups[key] ??= { day: '', count: 0, sinceReply: 0, lastReply: 0, lastSeen: 0, lastSender: '', lastText: '', lastAttempt: 0, lastResult: '' };
    }
    async function loadStatus() {
        if (statusLoaded) return statusLoaded;
        statusLoaded = (statusPath ? readFile(statusPath, 'utf8') : Promise.reject(Object.assign(new Error('no path'), { code: 'ENOENT' }))).then(text => {
            const value = JSON.parse(text);
            if (value?.schemaVersion === 1 && value.groups && typeof value.groups === 'object') status.groups = value.groups;
        }).catch(err => { if (err.code !== 'ENOENT') logger.warn(`主动回复状态读取失败: ${err.message}`); }).finally(saveStatus);
        return statusLoaded;
    }
    function saveStatus() {
        if (!statusPath || saveTimer) return;
        saveTimer = setTimeout(async () => {
            saveTimer = undefined;
            const tmp = `${statusPath}.tmp`;
            try {
                await mkdir(dir, { recursive: true });
                await writeFile(tmp, JSON.stringify({ ...status, updatedAt: Date.now() }), 'utf8');
                await rename(tmp, statusPath);
            } catch (err) { logger.warn(`主动回复状态保存失败: ${err.message}`); }
        }, 1000);
    }
    function record(gs, result, now = Date.now()) { gs.lastAttempt = now; gs.lastResult = result; saveStatus(); }
    async function load() {
        if (loading) return loading;
        if (!path || Date.now() - checked < 2000) return cached;
        checked = Date.now();
        loading = readFile(path, 'utf8').then(text => {
            const value = JSON.parse(text);
            cached = value && typeof value === 'object' && value.schemaVersion === 1 ? value : { global: {}, groups: {} };
            return cached;
        }).catch(err => {
            cached = { global: {}, groups: {} };
            if (err.code !== 'ENOENT') logger.warn(`主动回复配置读取失败: ${err.message}`);
            return cached;
        }).finally(() => { loading = undefined; });
        return loading;
    }
    function route(key) {
        try {
            const r = manager?.getEffectiveModel?.('group', key);
            if (r?.provider && r?.model) return r;
        } catch { /* fall through */ }
        return config.provider && config.model ? { provider: config.provider, model: config.model } : undefined;
    }
    async function persona(key) {
        try {
            const id = manager?.getEffectivePreset?.('group', key) ?? config.preset;
            if (!id) return '';
            const presets = host.get('agentPresets');
            return typeof presets?.prompt === 'function' ? (await presets.prompt(id)) || '' : '';
        } catch (err) {
            logger.warn(`主动回复读取角色卡失败: ${err instanceof Error ? err.message : String(err)}`);
            return '';
        }
    }
    function stateOf(key, gs, now) {
        let state = groups.get(key);
        if (!state) { state = { history: [], busy: false, lastMsg: undefined }; groups.set(key, state); }
        if (gs.day !== dayKey(now)) { gs.day = dayKey(now); gs.count = 0; }
        return state;
    }
    function remember(state, s, item) {
        state.history.push(item);
        if (state.history.length > s.historyMessages) state.history.splice(0, state.history.length - s.historyMessages);
    }
    /** 生成一条插话并以被动回复发出，返回结果文字。test=true 时不计入每日次数和冷却。 */
    async function speak(key, state, gs, s, msg, test) {
        const llm = host.get('llm');
        if (!llm?.stream) throw new Error('LLM 服务不可用');
        const r = route(key);
        if (!r) throw new Error('未配置模型');
        const system = [await persona(key), '你正在 QQ 群里潜水，看到下面的聊天后决定插一句话。回复要简短口语化（一两句），贴合上下文，不要用 Markdown 列表或标题，不要假装是其他群成员，不要复述别人的话；只输出要发送的内容。'].filter(Boolean).join('\n\n');
        const conversation = state.history.map(item => `${item.sender}: ${item.text}`).join('\n');
        const message = createUserMessage({ content: [{ type: 'text', text: `群聊最近的消息：\n${conversation}` }], source: { kind: 'plugin', plugin: 'dsh-im-qqbot' } });
        const assembler = new BlockAssembler();
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), TIMEOUT_MS);
        try {
            for await (const chunk of llm.stream({ provider: r.provider, model: r.model, system, messages: [message], maxTokens: MAX_TOKENS, signal: controller.signal })) assembler.push(chunk);
        } finally {
            clearTimeout(timeout);
        }
        if (assembler.finish?.kind === 'error' || assembler.finish?.kind === 'aborted') throw new Error(assembler.finish.failure?.message || (assembler.finish.kind === 'aborted' ? '生成超时' : 'LLM 生成失败'));
        const reply = assembler.blocks().filter(block => block.type === 'text').map(block => block.text).join('').trim().slice(0, 500);
        if (!reply) { logger.warn(`主动回复为空 model=${r.model} finish=${assembler.finish?.kind ?? 'unknown'}`); return '模型返回空内容'; }
        if (!test) {
            checked = 0;
            const latest = await load();
            if (!settings(latest.global, latest.groups?.[key]).enabled) return '已关闭，丢弃';
        }
        if (Date.now() - msg.time > PASSIVE_WINDOW_MS) return '超过被动回复窗口，丢弃';
        await bot.send({ target: { scope: 'group', targetId: key, msgId: msg.messageId }, msgType: 2, markdown: { content: reply } });
        const sent = new Date();
        if (!test) {
            if (gs.day !== dayKey(sent)) { gs.day = dayKey(sent); gs.count = 0; }
            gs.count++; gs.lastReply = sent.getTime(); gs.sinceReply = 0;
        }
        remember(state, s, { text: reply, sender: '我（机器人）', time: sent.getTime() });
        logger.info(`主动回复已发送${test ? '（测试）' : ''} group=${key} model=${r.model} count=${gs.count}`);
        return test ? `测试已发送：${reply.slice(0, 40)}` : '已发送';
    }
    async function observe(msg) {
        await loadStatus();
        const cfg = await load();
        const key = msg.groupOpenid;
        const s = settings(cfg.global, cfg.groups?.[key]);
        const now = new Date(), time = now.getTime();
        const gs = groupStatus(key);
        const text = cleanText(msg.content);
        const previousSeen = gs.lastSeen;
        gs.lastSeen = time; gs.lastSender = msg.senderName || msg.senderId || ''; gs.lastText = text.slice(0, 60);
        saveStatus();
        if (!text) return;
        const state = stateOf(key, gs, now);
        // 关闭时也记上下文（仅内存、有条数上限），"立即测试一次"才有内容可用。
        remember(state, s, { text, sender: msg.senderName || msg.senderId, time });
        if (msg.messageId) state.lastMsg = { messageId: msg.messageId, time };
        if (!s.enabled || !plain(msg)) return; // @机器人/引用等交给普通会话，只记入上下文
        gs.sinceReply = (gs.sinceReply ?? 0) + 1;
        if (text.length < s.minTextLength || text.length > s.maxTextLength) return;
        if (state.busy || quiet(s, now) || gs.sinceReply < s.minMessages || gs.count >= s.dailyLimitPerGroup || time - gs.lastReply < s.cooldownSeconds * 1000 || (s.requireRecentActivitySeconds > 0 && (!previousSeen || time - previousSeen > s.requireRecentActivitySeconds * 1000)) || Math.random() * 100 >= s.probability) return;
        state.busy = true;
        try {
            record(gs, await speak(key, state, gs, s, { messageId: msg.messageId, time }, false));
        } catch (err) {
            const reason = err instanceof Error ? err.message : String(err);
            logger.warn(`主动回复失败: ${reason}`);
            record(gs, `失败：${reason.slice(0, 120)}`);
        }
        finally { state.busy = false; }
    }
    /**
     * App 里点"立即测试一次"会写 proactive-reply-test.json。
     * 跳过开关/概率/冷却/次数/安静时段，但仍要用最近一条群消息的 msgId 做被动回复。
     */
    let testing = false;
    async function pollTest() {
        if (!testPath || testing) return;
        let request;
        try { request = JSON.parse(await readFile(testPath, 'utf8')); } catch { return; }
        testing = true;
        try {
            await unlink(testPath).catch(() => { });
            await loadStatus();
            const key = typeof request?.group === 'string' ? request.group : '';
            if (!key) return;
            const gs = groupStatus(key);
            const finish = result => { gs.lastTest = Date.now(); gs.lastTestId = String(request.id ?? ''); gs.lastTestResult = result; record(gs, result); };
            if (!config.requireMention) return finish('失败：已关闭"群聊必须@"，主动回复不工作');
            const cfg = await load();
            const s = settings(cfg.global, cfg.groups?.[key]);
            const state = stateOf(key, gs, new Date());
            if (!state.lastMsg || Date.now() - state.lastMsg.time > PASSIVE_WINDOW_MS) return finish('失败：最近 4.5 分钟内没收到这个群的消息，先在群里发一句再测');
            if (state.busy) return finish('失败：正在生成上一条，稍后再试');
            state.busy = true;
            try { finish(await speak(key, state, gs, s, state.lastMsg, true)); }
            catch (err) { const reason = err instanceof Error ? err.message : String(err); logger.warn(`主动回复测试失败: ${reason}`); finish(`失败：${reason.slice(0, 120)}`); }
            finally { state.busy = false; }
        } finally { testing = false; }
    }
    const testTimer = setInterval(() => { void pollTest(); }, 2000);
    testTimer.unref?.();
    void loadStatus();
    return async (mCtx, next) => {
        if (config.requireMention && isGroupText(mCtx.message)) void observe(mCtx.message).catch(err => logger.warn(`主动回复观察失败: ${err.message}`));
        await next();
    };
}
